import sqlite3, os
for f in ['/workspace/world.db']:
    try:
        conn = sqlite3.connect(f)
        cur = conn.cursor()
        tables = cur.execute(\"SELECT name FROM sqlite_master WHERE type='table'\").fetchall()
        for t in tables:
            cols = [c[1] for c in cur.execute(f'PRAGMA table_info({t[0]})').fetchall()]
